function origin(){return(process.env.ALPHALAB_API_ORIGIN||'http://127.0.0.1:8000').replace(/\/+$/,'')}
async function get(path){const response=await fetch(origin()+path,{headers:{Accept:'application/json'}});if(!response.ok)throw new Error('AlphaLab API '+response.status+': '+await response.text());return response.json()}
function delay(ms){return new Promise(resolve=>setTimeout(resolve,ms))}
async function run(input){if(input.confirm_python_execution!==true)throw new Error('Backtest requires explicit Python execution confirmation');const id=String(input.project_id||'').trim();if(!id)throw new Error('project_id is required');const base='/api/strategy/projects/'+encodeURIComponent(id);const [project,validation]=await Promise.all([get(base),get('/api/validation/projects/'+encodeURIComponent(id))]);if(project.dirty)throw new Error('Save the project source before running a backtest');const revision=Number(project.current_revision);const pkg=await get(base+'/revisions/'+revision);const response=await fetch(origin()+'/api/backtests/jobs',{method:'POST',headers:{Accept:'application/json','Content-Type':'application/json'},body:JSON.stringify({project_id:id,revision,start_date:String(input.start_date),end_date:String(input.end_date),profile:'runtime',confirm_python_execution:true})});if(!response.ok)throw new Error('AlphaLab API '+response.status+': '+await response.text());let job=await response.json();const deadline=Date.now()+840000;while(job.status==='queued'||job.status==='running'){if(Date.now()>=deadline)throw new Error('Backtest job '+job.id+' is still running and can be inspected later');await delay(2000);job=await get('/api/backtests/jobs/'+encodeURIComponent(job.id))}if(job.status!=='succeeded'||!job.result)throw new Error(job.error||job.message||'Backtest job failed');const result=job.result;if(result.revision!==revision||result.source_sha256!==pkg.source_sha256)throw new Error('Strategy source package changed during backtest');if(result.validation_revision!==validation.current_revision||result.validation_source_sha256!==validation.source_sha256)throw new Error('Validation source package changed during backtest');return{...result,job_id:job.id,strategy_source_package:{project_id:id,revision,source_sha256:pkg.source_sha256},validation_source_package:{project_id:id,revision:validation.current_revision,source_sha256:validation.source_sha256}}}
